/**
 * Laban's Bargain
 * ---------------
 * Laban deceives Jacob with Leah's veiled marriage, and Jacob serves seven more years for Rachel; the wages change like the weather. Stage: a wedding tent at night with a veil and a sister's face, a contract of years, a flock passing between the brothers-in-law; a lamp, a bargain, a long game.
 *
 * Palette 0x241810 → 0x060402 · light: dusk · hero: tent
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./jacob-kit.js.
 */

import { THREE, createScene, tent, firepit, sheep, person } from './jacob-kit.js';

const BG = 0x241810;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 2593754929, bg: BG, fogNear: 50, fogFar: 200 });

    /* light — dusk */
    W.lights({ sky: 0x7a5a8c, gnd: 0x3a2a1a, hemi: 0.6, sun: 0xff9a50, sunI: 0.85, sunPos: [45, 12, -18] });

    W.disc([55, 22, -140], 12, 0xff9a50);
    W.disc([55, 22, -150], 20, 0xff7a30, 0.18);
    W.stars(30, 150, [0xd8c8e8, 0xc8b8d8], 0.5);
    W.disc([-60, 40, -150], 30, 0x4a3a5c, 0.25);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* camp: a circle of tents, smoke rising */
    tent(W, group, 26.0, 0, -6.8, 1.26, 0x8a6a44, W.r() * 6);
    tent(W, group, 19.0, 0, -16.8, 1.16, 0xd8c8a0, W.r() * 6);
    tent(W, group, -2.2, 0, -7.8, 1.36, 0xc8b088, W.r() * 6);
    firepit(W, group, -6.2, 0, -1.4, 1.0);

    /* flock: sheep grazing */
    sheep(W, group, -16.7, 0, -9.7, W.r() * 6, 1.04);
    sheep(W, group, -5.1, 0, 11.3, W.r() * 6, 1.01);
    sheep(W, group, -11.1, 0, 5.0, W.r() * 6, 1.20);
    sheep(W, group, -10.3, 0, -3.5, W.r() * 6, 1.17);

    /* hero: the tent */
    tent(W, group, 0, 0, 0, 1.4, 0x060402, 0.2);
    W.disc([0, 5, -10], 5, 0x2f1f15, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x241810, head: 'wrap', wrap: 0x291c12, wrapTrim: 0x19110b, staff: 'planted', ry: 0.52, s: 1.17 });
    person(W, group, [4.5, 0, 6], { robe: 0x060402, head: 'wrap', wrap: 0x291c12, wrapTrim: 0x19110b, staff: 'planted', ry: -0.62, s: 1.14 });

    return W.finish();
}

export default { build };
